const input = $input.first().json;
const body = input.body ?? input;

const message = String(body.message ?? '').trim();
const userId = Number(body.user_id ?? 0) || 0;
let knowledge = String(body.knowledge_context ?? '');
if (knowledge.length > 10000) {
  knowledge = knowledge.slice(0, 10000);
}

const knowledgeBlock = knowledge
  ? `\n\n---\n${knowledge}\n---\n`
  : '';

const studentLine = message || '(empty message)';

const prompt = `You are CodeCraft AI Instructor — a friendly coding teacher for beginners.

TOPIC RULE (very important):
- If the user message is NOT about programming, software, coding, debugging, or learning to code, reply with EXACTLY this one sentence and nothing else:
I am CodeCraft AI Instructor and I can only help with programming and software development learning.
- Otherwise teach in simple steps with short examples. Be warm and encouraging.

ALLOW: Python, JavaScript, Java, C, React, debugging, learning to code, and CodeCraft tracks/modules/lessons when context is below.
BLOCK: politics, medical, legal, sports, recipes, unrelated homework.
${knowledgeBlock}
Student user_id: ${userId}

Student message:
${studentLine}`;

return [{
  json: {
    message,
    user_id: userId,
    prompt,
    model: 'gemini-2.0-flash'
  }
}];

const gemini = $input.first().json;

const text = gemini?.candidates?.[0]?.content?.parts?.[0]?.text;
if (typeof text === 'string' && text.trim()) {
  return [{ json: { success: true, reply: text.trim() } }];
}

const apiError = gemini?.error?.message || gemini?.error?.status;
const reply = apiError
  ? `Gemini API error: ${apiError}`
  : 'Gemini returned no text. Check Header Auth credential (x-goog-api-key) on Call Gemini API node.';

return [{ json: { success: false, reply } }];
